    uint8_t *copy = malloc(size);
    if (copy == NULL) {
        abort();
    }
    memcpy(copy, data, size);
    // hopen does not take ownership of `copy`, but hts_hopen does.
    memfile = hopen("mem:", "rb:", copy, size);
    if (memfile == NULL) {
        free(copy);
        return 0;
    }

    htsFile *ht_file = hts_hopen(memfile, "data", "rb");
    if (ht_file == NULL) {
        if (hclose(memfile) != 0) {
            abort();
        }
        return 0;
    }
    switch (ht_file->format.category) {
        case sequence_data:
            view_sam(ht_file);
            break;
        case variant_data:
            view_vcf(ht_file);
            break;
        default:
            break;
    }

    if (size > 0) {
        char *fn = malloc(size + 16);
        if (!fn) abort();
        memcpy(fn, data, size);
        memcpy(fn + size, "##idx##X", 8);
        htsFile *idx = hts_open(fn, "r");
        free(fn);
        if (idx) hts_close_or_abort(idx);
    }

    if (size > 0) {
        char *fn = malloc(size + 16);
        if (!fn) abort();
        memcpy(fn, data, size);
        memcpy(fn + size, "##idx##X", 8);
        htsFile *idx = hts_open(fn, "r");
        free(fn);
        if (idx) hts_close_or_abort(idx);
    }
    hts_close_or_abort(ht_file);
    return 0;

